import {AssessmentSettingsSection,type AssessmentSettingsInjected} from './AssessmentSettingsSection.tsx';
import {createAssessmentApi} from './assessment-api.ts';
import {zh as assessmentZh,en as assessmentEn} from './assessment-locales.ts';
import { BudgetSettingsSection, type BudgetSettingsSectionInjected } from './BudgetSettingsSection.tsx';
import { createBudgetSettingsApi } from './budget-api.ts';
import { en as budgetEn, zh as budgetZh } from './budget-locales.ts';
import type { Context as ClientContext } from '@deepseek-ai/cordis';
import type { ConnectionHandle } from '@deepseek-ai/dsh-client-connection/client';
import type {} from '@deepseek-ai/dsh-client-locale/client';
import type {} from '@deepseek-ai/dsh-client-ui-settings/client';
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client';
import { MemorySettingsSection, type MemorySettingsSectionInjected } from './MemorySettingsSection.tsx';
import { createMemorySettingsApi } from './api.ts';
import { en, zh } from './locales.ts';
import { resolveConfig, type MemoryUiConfig } from '../config.ts';
export { Config } from '../config.ts';
export type { MemorySettingsSectionInjected, MemorySettingsSectionProps } from './MemorySettingsSection.tsx';
export type { MemoryUiConfig } from '../config.ts';
/** Native slot, locale and private transport dependencies. */
export const inject = ['slots', 'locale', 'connection'];
/** Register one project memory settings section without adding a session mode. */
export function apply(ctx: ClientContext, config: MemoryUiConfig = {}): void {
  const resolved = resolveConfig(config);
  if (!resolved.enabled) return;
  const namespace = 'settings.sepMemory';
  ctx.effect(() => ctx.locale.register(namespace, { zh, en }), 'memory settings dictionaries');
  const t = ctx.locale.bind(namespace);
  const connection = ctx.get('connection') as ConnectionHandle;
  const api = createMemorySettingsApi(connection.rpc);
  const injected: MemorySettingsSectionInjected = { api, requestTimeoutMs: resolved.requestTimeoutMs, hooks: { connection: connection.generation } };
  ctx.slots.inject('settings.section', () => ctx.slots.register({ name: 'settings.section', id: 'sep-memory', order: 35, label: () => t('title'), locale: namespace, inject: () => injected }, MemorySettingsSection));
  const assessmentNamespace='settings.sepAssessment';
  ctx.effect(()=>ctx.locale.register(assessmentNamespace,{zh:assessmentZh,en:assessmentEn}),'update assessment dictionaries');
  const assessmentT=ctx.locale.bind(assessmentNamespace);
  const assessmentInjected:AssessmentSettingsInjected={api:createAssessmentApi(connection.rpc),requestTimeoutMs:resolved.requestTimeoutMs,hooks:{connection:connection.generation}};
  ctx.slots.inject('settings.section',()=>ctx.slots.register({name:'settings.section',id:'sep-assessment',order:37,label:()=>assessmentT('title'),locale:assessmentNamespace,inject:()=>assessmentInjected},AssessmentSettingsSection));
  const budgetNamespace = 'settings.sepBudget';
  ctx.effect(() => ctx.locale.register(budgetNamespace, { zh: budgetZh, en: budgetEn }), 'budget settings dictionaries');
  const budgetT = ctx.locale.bind(budgetNamespace);
  const budgetInjected: BudgetSettingsSectionInjected = { api: createBudgetSettingsApi(connection.rpc), requestTimeoutMs: resolved.requestTimeoutMs, hooks: { connection: connection.generation } };
  ctx.slots.inject('settings.section', () => ctx.slots.register({ name: 'settings.section', id: 'sep-budget', order: 36, label: () => budgetT('title'), locale: budgetNamespace, inject: () => budgetInjected }, BudgetSettingsSection));
}
